grep -rn "Discount\|Total()\|Items" . ; mkdir -p /tmp/repro && cat > pricing/pricing_test.go <<'EOF'
package pricing

import "testing"

func TestTotal(t *testing.T) {
	items := []*Item{{Name: "a", Cents: 1000, Qty: 2}, {Name: "b", Cents: 500, Qty: 1}}
	tests := []struct {
		name string
		cart Cart
		want int
	}{
		{"no discount", Cart{Items: items}, 2500},
		{"with discount", Cart{Items: items, Discount: &Discount{Percent: 10}}, 2250},
		{"empty cart", Cart{}, 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.cart.Total(); got != tt.want {
				t.Errorf("Total() = %d, want %d", got, tt.want)
			}
		})
	}
}
EOF
go test ./pricing/ 2>&1 | head -20

